@rule("s23", "s0", otherwise="NotMentioned")
def query_result():
    return "Contradiction" if "reverse engineer" in "Receiving Party shall not reverse engineer any objects which embody Disclosing Party's Confidential Information." else "NotMentioned"

@scope("s6")
def applicability():
    return True

@rule("s6", "s0", otherwise="NotMentioned")
def confidentiality():
    return "Entailment" if "maintain all nonpublic information" in "The Stilwell Group expressly agrees to maintain all nonpublic information concerning the Company and its subsidiaries in confidence." else "NotMentioned"

@rule("s7", "s0", otherwise="NotMentioned")
def authorization():
    return "Entailment" if "duly and validly authorized" in "Each of the Stilwell Group and Schneider represents and warrants to the Company that this Agreement has been duly and validly authorized (in the case of the entity members of the Stilwell Group), executed and delivered by them, and is a valid and binding agreement enforceable against them in accordance with its terms." else "NotMentioned"

@rule("s8", "s0", otherwise="NotMentioned")
def representation():
    return "Entailment" if "satisfies all of the qualifications" in "Schneider hereby further represents and warrants to the Company that: (a) he satisfies all of the qualifications to be a director of the Company as set forth in Article III, Section 4 of the Company's bylaws and any additional applicable qualifications under the laws of the State of Washington or under the regulations of any bank regulatory authority, and that he is not in any way precluded from serving as a director by order or other action of any court, regulatory or other governmental authority;" else "NotMentioned"

@rule("s9", "s0", otherwise="NotMentioned")
def breach():
    return "Entailment" if "monetary damages may not be a sufficient remedy" in "The Stilwell Group acknowledges that with regard to its obligations to maintain the confidentiality of nonpublic information of the Company and its subsidiaries, monetary damages may not be a sufficient remedy for any breach or threatened breach of this Agreement and that, in addition to all other remedies, the Company may be entitled to seek specific performance and injunctive or other equitable relief as a remedy for such breach, and in conjunction therewith the Company shall not be required to post any bond." else "NotMentioned"

@rule("s10", "s0", otherwise="NotMentioned")
def entire_agreement():
    return "Entailment" if "entire agreement" in "This Agreement constitutes the entire agreement between the parties hereto pertaining to the subject matter hereof and supersedes all prior and contemporaneous agreements, understandings, negotiations and discussions of the parties in connection therewith not referred to herein." else "NotMentioned"

@rule("s11", "s0", otherwise="NotMentioned")
def governing_law():
    return "Entailment" if "governed by, and construed in accordance with the laws of the State of Washington" in "This Agreement shall be governed by, and construed in accordance with the laws of the State of Washington, without regard to choice of law principles that may otherwise compel the application of the laws of any other jurisdiction." else "NotMentioned"

@rule("s12", "s0", otherwise="NotMentioned")
def severable():
    return "Entailment" if "terms and provisions of this agreement shall be deemed severable" in "The terms and provisions of this agreement shall be deemed severable, and in the event any term or provision hereof or portion thereof is deemed or held to be invalid, illegal or unenforceable, such provision shall be conformed to prevailing law rather than voided, if possible, in order to achieve the intent of the parties, and, in any event, the remaining terms and provisions of this agreement shall nevertheless continue and be deemed to be in full force and effect and binding upon the parties." else "NotMentioned"

@rule("s13", "s0", otherwise="NotMentioned")
def survive():
    return "Entailment" if "representations, warranties, covenants and agreements made herein shall survive" in "All representations, warranties, covenants and agreements made herein shall survive the execution and delivery of this Agreement." else "NotMentioned"

@rule("s14", "s0", otherwise="NotMentioned")
def modification():
    return "Entailment" if "modified, amended, altered or supplemented" in "This Agreement may not be modified, amended, altered or supplemented except upon the execution and delivery of a written agreement executed by all of the parties hereto." else "NotMentioned"

@rule("s15", "s0", otherwise="NotMentioned")
def counterparts():
    return "Entailment" if "executed in counterparts" in "This Agreement may be executed in counterparts, each of which shall be an original, but all of which together shall constitute one and the same agreement." else "NotMentioned"

@rule("s16", "s0", otherwise="NotMentioned")
def execution():
    return "Entailment" if "duly executed and delivered by duly authorized officers" in "IN WITNESS WHEREOF, this Agreement has been duly executed and delivered by duly authorized officers of the undersigned as of the day and year first above written." else "NotMentioned"

@rule("s17", "s0", otherwise="NotMentioned")
def stilwell_group():
    return "Entailment" if "THE STILWELL GROUP" in "THE STILWELL GROUP FIRST FINANCIAL NORTHWEST, INC." else "NotMentioned"

@rule("s18", "s0", otherwise="NotMentioned")
def signatures():
    return "Entailment" if "By: /s/ Joseph Stilwell By: /s/Victor Karpiak" in "By: /s/ Joseph Stilwell By: /s/Victor Karpiak" else "NotMentioned"

@rule("s19", "s0", otherwise="NotMentioned")
def joseph_stilwell():
    return "Entailment" if "Joseph Stilwell Victor Karpiak, Chairman, President and Chief Executive Officer" in "Joseph Stilwell Victor Karpiak, Chairman, President and Chief Executive Officer" else "NotMentioned"

@rule("s20", "s0", otherwise="NotMentioned")
def spencer_schneider():
    return "Entailment" if "SPENCER L. SCHNEIDER" in "SPENCER L. SCHNEIDER" else "NotMentioned"

@rule("s21", "s0", otherwise="NotMentioned")
def spencer_schneider_signature():
    return "Entailment" if "/s/Spencer L. Schneider" in "/s/Spencer L. Schneider" else "NotMentioned"

@rule("s22", "s0", otherwise="NotMentioned")
def spencer_schneider_name():
    return "Entailment" if "Spencer L. Schneider" in "Spencer L. Schneider" else "NotMentioned"

